select private.course_insert_item('m20', '20.assignment', $j${"id":"20.6","type":"lesson","title":"20.6 The Compliance Quiz","shortTitle":"20.6 Compliance Quiz","bodyMarkdown":"This is the compliance quiz. It checks the rules you have to follow on every call before anyone signs off on you calling real sellers. It isn't new material: everything here comes from Lesson 4.10, Lesson 7.8 and Module 13.\n\n**What it covers**\n\n| Area | Where it's taught |\n|---|---|\n| Calling hours, Do Not Call, consent for texts | Lessons 4.10 and 7.8 |\n| Recording calls and the all-party states | Lesson 13.5 |\n| Ohio's disclosure, line by line | Lesson 13.2 |\n| The state map and the five habits | Lesson 13.3 |\n| Marketing a contract, not a house | Lesson 13.4 |\n| Lines you never cross | Lesson 13.6 |\n\n**How it works**\n\n- 20 questions. The pass mark is 90%, so 18 of 20.\n- Passing it is one of the certification requirements, and Amr checks it before signing your live-call readiness checklist.\n- Missed a question? Read the lesson named in the explanation, then retake the quiz. There's no limit on tries.\n\n**Your work for this lesson:** reread the \"What to remember\" list in Lesson 7.8 and the five habits in Lesson 13.3, then take the quiz.\n\n**بالعربي، باختصار**\n\n⁧اختبار الـ compliance: ٢٠ سؤال عن مواعيد الاتصال، الـ Do Not Call، الموافقة على الرسايل، تسجيل المكالمات، والـ disclosure في أوهايو وقوانين الولايات. لازم تجيب ٩٠٪ (١٨ من ٢٠). ده شرط من شروط الشهادة، وAmr بيراجعه قبل ما يوقّع إنك جاهز للمكالمات الحقيقية.⁩","quiz":{"id":"quiz-20.6","title":"Quiz 20.6","passMark":90,"questions":[{"id":"m20-20-6-q01","type":"single","number":1,"prompt":"What is Ridgeway's calling window?","options":[{"id":"A","text":"9 AM to 8 PM in the seller's time zone","correct":true},{"id":"B","text":"8 AM to 9 PM in your own time zone","correct":false},{"id":"C","text":"9 AM to 8 PM Eastern for every state","correct":false},{"id":"D","text":"Any time before 9 PM if the seller answered before","correct":false}],"explanation":"Lesson 7.8. The company window sits inside the federal 8 AM to 9 PM limit."},{"id":"m20-20-6-q02","type":"single","number":2,"prompt":"Federal rules allow sales calls between which hours?","options":[{"id":"A","text":"7 AM and 10 PM, the caller's local time","correct":false},{"id":"B","text":"8 AM and 9 PM, the seller's local time","correct":true},{"id":"C","text":"9 AM and 5 PM on weekdays only","correct":false},{"id":"D","text":"Any hour, if the number isn't on the Do Not Call list","correct":false}],"explanation":"Lesson 7.8."},{"id":"m20-20-6-q03","type":"single","number":3,"prompt":"A seller says, \"Take me off your list.\" What do you do?","options":[{"id":"A","text":"Ask once more if they're sure, then mark it next week","correct":false},{"id":"B","text":"Stop calling but keep texting with good offers","correct":false},{"id":"C","text":"Mark do-not-call now and never contact them again","correct":true},{"id":"D","text":"Hand the lead to a teammate to try a softer approach","correct":false}],"explanation":"Lesson 7.8. Ridgeway honors it the same day."},{"id":"m20-20-6-q04","type":"single","number":4,"prompt":"At most, how long do federal rules give a company to honor a do-not-call request?","options":[{"id":"A","text":"24 hours","correct":false},{"id":"B","text":"30 calendar days","correct":false},{"id":"C","text":"90 days, the length of a nurture cycle","correct":false},{"id":"D","text":"10 business days","correct":true}],"explanation":"Lesson 7.8. The company standard is stricter: same day."},{"id":"m20-20-6-q05","type":"single","number":5,"prompt":"Which numbers may you text?","options":[{"id":"A","text":"Only numbers marked \"consent\" in the CRM","correct":true},{"id":"B","text":"Any number on a scrubbed cold list","correct":false},{"id":"C","text":"Any cell number you've called once","correct":false},{"id":"D","text":"Any number the seller didn't put on the Do Not Call Registry","correct":false}],"explanation":"Lesson 7.8. Sales texts need written consent."},{"id":"m20-20-6-q06","type":"single","number":6,"prompt":"You pulled a number from a list with no consent on file and want to reach the owner. What's right?","options":[{"id":"A","text":"Send one short text, since one is allowed","correct":false},{"id":"B","text":"Call by hand instead of texting","correct":true},{"id":"C","text":"Text from your personal phone so it isn't a business text","correct":false},{"id":"D","text":"Text, then ask for consent in the message","correct":false}],"explanation":"Lesson 7.8. Not sure about consent? Call by hand."},{"id":"m20-20-6-q07","type":"single","number":7,"prompt":"A seller texts back \"stop.\" What does that end?","options":[{"id":"A","text":"Texts only; calls can continue","correct":false},{"id":"B","text":"Texts for 30 days","correct":false},{"id":"C","text":"All texts and calls to that number","correct":true},{"id":"D","text":"Nothing until they confirm in writing","correct":false}],"explanation":"Lesson 7.8. One stop ends all contact."},{"id":"m20-20-6-q08","type":"single","number":8,"prompt":"You're calling a seller in Florida and record your calls. What do you do?","options":[{"id":"A","text":"Record silently, since your own state only needs one party","correct":false},{"id":"B","text":"Record and tell them at the end of the call","correct":false},{"id":"C","text":"Skip the notice if the call is under five minutes","correct":false},{"id":"D","text":"Tell them at the start and record only if they agree","correct":true}],"explanation":"Lesson 13.5. Florida is an all-party consent state."},{"id":"m20-20-6-q09","type":"single","number":9,"prompt":"How do you treat Delaware for call recording?","options":[{"id":"A","text":"As all-party consent","correct":true},{"id":"B","text":"As one-party consent","correct":false},{"id":"C","text":"As if recording is banned","correct":false},{"id":"D","text":"As whatever your own state allows","correct":false}],"explanation":"Lesson 13.5. Its two laws conflict, so take the stricter reading."},{"id":"m20-20-6-q10","type":"single","number":10,"prompt":"The seller and the rep are in states with different recording rules. Which rule applies?","options":[{"id":"A","text":"The rep's state","correct":false},{"id":"B","text":"The stricter state's rule","correct":true},{"id":"C","text":"The seller's state, only if it's stricter in writing","correct":false},{"id":"D","text":"Whichever state the company is registered in","correct":false}],"explanation":"Lessons 7.8 and 13.5."},{"id":"m20-20-6-q11","type":"single","number":11,"prompt":"In Ohio, when must the wholesaler disclosure be signed?","options":[{"id":"A","text":"At closing, together with the deed and other documents","correct":false},{"id":"B","text":"Within 3 days after the agreement is signed","correct":false},{"id":"C","text":"Before the owner signs the purchase agreement","correct":true},{"id":"D","text":"Only if the contract is assigned","correct":false}],"explanation":"Lesson 13.2."},{"id":"m20-20-6-q12","type":"single","number":12,"prompt":"What does Ohio require the disclosure to look like?","options":[{"id":"A","text":"One sentence anywhere inside the purchase agreement itself","correct":false},{"id":"B","text":"A verbal notice on a recorded call","correct":false},{"id":"C","text":"An email sent before closing","correct":false},{"id":"D","text":"A separate, bold 12-point notice signed by both","correct":true}],"explanation":"Lesson 13.2, ORC 5301.95."},{"id":"m20-20-6-q13","type":"single","number":13,"prompt":"An Ohio deal was signed without the disclosure. What can the owner do?","options":[{"id":"A","text":"Cancel any time before closing, without penalty","correct":true},{"id":"B","text":"Nothing at all once the agreement has been signed","correct":false},{"id":"C","text":"Cancel within 3 days only","correct":false},{"id":"D","text":"Ask for a higher price but not cancel","correct":false}],"explanation":"Lesson 13.2."},{"id":"m20-20-6-q14","type":"single","number":14,"prompt":"What does Missouri's 2026 law (SB 973) require?","options":[{"id":"A","text":"A broker license for every deal, including the first one","correct":false},{"id":"B","text":"A signed disclosure 14+ days before any contract","correct":true},{"id":"C","text":"Disclosure at closing","correct":false},{"id":"D","text":"Nothing for houses, only for land","correct":false}],"explanation":"Lessons 13.3 and 20.5."},{"id":"m20-20-6-q15","type":"single","number":15,"prompt":"In Illinois, when does wholesaling need a broker license?","options":[{"id":"A","text":"From the first deal","correct":false},{"id":"B","text":"Only for deals over $250,000","correct":false},{"id":"C","text":"From two or more deals in 12 months","correct":true},{"id":"D","text":"Never, if the seller signs a disclosure","correct":false}],"explanation":"Lesson 13.3."},{"id":"m20-20-6-q16","type":"single","number":16,"prompt":"In states like Kentucky and South Carolina, what counts as brokerage?","options":[{"id":"A","text":"Calling sellers from a scrubbed list during calling hours","correct":false},{"id":"B","text":"Assigning a contract to a buyer you know","correct":false},{"id":"C","text":"Recording a call for training","correct":false},{"id":"D","text":"Publicly advertising a house you only have under contract","correct":true}],"explanation":"Lessons 13.3 and 13.4. Market the contract, not the house."},{"id":"m20-20-6-q17","type":"single","number":17,"prompt":"A seller asks whether selling will hurt their taxes. What do you say?","options":[{"id":"A","text":"\"I can't advise on that. A tax pro can.\"","correct":true},{"id":"B","text":"Give your best estimate so they keep moving","correct":false},{"id":"C","text":"\"It usually doesn't matter for a house like yours.\"","correct":false},{"id":"D","text":"\"Our title company will handle that part.\"","correct":false}],"explanation":"Lesson 13.6. Never give legal or tax advice; refer out."},{"id":"m20-20-6-q18","type":"single","number":18,"prompt":"A manager tells you to skip the disclosure \"just this once\" to save a deal. What do you do?","options":[{"id":"A","text":"Skip it if the seller seems relaxed","correct":false},{"id":"B","text":"Refuse and raise it with compliance","correct":true},{"id":"C","text":"Send it after the seller signs","correct":false},{"id":"D","text":"Mention it out loud instead of in writing","correct":false}],"explanation":"Lessons 7.8 and 13.6. Stop and ask."},{"id":"m20-20-6-q19","type":"single","number":19,"prompt":"You're about to call into a state that isn't in the Lesson 13.3 table. What's true?","options":[{"id":"A","text":"It has no wholesaling rules, so go ahead and call as usual","correct":false},{"id":"B","text":"Use Ohio's rules everywhere","correct":false},{"id":"C","text":"It still has rules; ask the company's attorney","correct":true},{"id":"D","text":"Only federal rules apply there","correct":false}],"explanation":"Lesson 13.3. Missing from the table is not a no-rules state."},{"id":"m20-20-6-q20","type":"single","number":20,"prompt":"Which habit covers almost every new wholesaling law?","options":[{"id":"A","text":"Close as fast as possible so the seller can't cancel","correct":false},{"id":"B","text":"Avoid mentioning assignment","correct":false},{"id":"C","text":"Only work in states without a law","correct":false},{"id":"D","text":"Disclose in writing, before the seller signs","correct":true}],"explanation":"Lesson 13.3, the five habits."}]},"practice":{"drills":[{"title":"Say the rule","level":"respond","intro":"Say the rule out loud, then what you do on the call.","themLabel":"Situation","youLabel":"Rule and action","pairs":[{"them":"A seller in Arizona picks up at 8:20 PM Eastern.","you":"That's 6:20 PM for him, inside our window. Go ahead.","why":"Always the seller's time zone."},{"them":"\"Stop calling me.\"","you":"\"Done. I'm sorry for the bother.\" Mark do-not-call now.","why":"Same day, every time."},{"them":"A Pennsylvania seller, and you record your calls.","you":"Give the recording notice and record only with a yes.","why":"Pennsylvania is all-party."},{"them":"An Ohio seller is ready to sign today.","you":"The signed disclosure comes first, then the agreement.","why":"ORC 5301.95."}]}]},"drillBank":[{"id":"m20-20-6-d01","type":"single","number":21,"prompt":"When is a call to a seller in California at 7:45 PM Pacific fine for Ridgeway?","options":[{"id":"A","text":"Yes, it's inside 9 AM to 8 PM in the seller's zone","correct":true},{"id":"B","text":"No, it's 10:45 PM Eastern","correct":false},{"id":"C","text":"Only with written consent","correct":false},{"id":"D","text":"Only on weekdays","correct":false}],"explanation":"Lesson 7.8. Always the seller's time zone."},{"id":"m20-20-6-d02","type":"single","number":22,"prompt":"Your opener for a recorded call should include…","options":[{"id":"A","text":"Nothing; recording is internal","correct":false},{"id":"B","text":"A recording notice and the seller's okay","correct":true},{"id":"C","text":"A notice only in all-party states","correct":false},{"id":"D","text":"A notice at the end","correct":false}],"explanation":"Lesson 13.5. Say it every time."},{"id":"m20-20-6-d03","type":"single","number":23,"prompt":"Who decides whether a memorandum of contract is recorded?","options":[{"id":"A","text":"The rep, if the seller seems unsure","correct":false},{"id":"B","text":"The buyer","correct":false},{"id":"C","text":"The company's attorney","correct":true},{"id":"D","text":"The title company, always","correct":false}],"explanation":"Lesson 13.4."},{"id":"m20-20-6-d04","type":"single","number":24,"prompt":"A deal blast should never include…","options":[{"id":"A","text":"The property's condition","correct":false},{"id":"B","text":"The assignment fee","correct":false},{"id":"C","text":"Showing times","correct":false},{"id":"D","text":"The seller's name, phone or private situation","correct":true}],"explanation":"Lesson 13.4."}]}$j$::jsonb);
update public.course_modules set content = private.course_put_item(content, '6.2', private.course_get_item(content, '6.2') || jsonb_build_object('drillBank', coalesce(private.course_get_item(content, '6.2')->'drillBank','[]'::jsonb) || $j$[{"id":"m7-6-2-d10","type":"single","number":10,"prompt":"A lead scores 3 on motivation, 2 on timeline, 2 on condition and 1 on price. What do you do?","options":[{"id":"A","text":"Warm: appointment or follow-up within a week","correct":true},{"id":"B","text":"Mark it dead and move on to the next lead in the queue","correct":false},{"id":"C","text":"Monthly nurture","correct":false},{"id":"D","text":"Hot: hand it to the AM right now","correct":false}],"explanation":"Lesson 6.2. 8 is warm."},{"id":"m7-6-2-d11","type":"single","number":11,"prompt":"Which pillar outweighs the others?","options":[{"id":"A","text":"Price","correct":false},{"id":"B","text":"Condition","correct":false},{"id":"C","text":"Timeline, since speed wins deals","correct":false},{"id":"D","text":"Motivation","correct":true}],"explanation":"Lesson 6.2. A real problem often brings the price down."}]$j$::jsonb)) where id = 'm7';
update public.course_modules set content = private.course_put_item(content, '6.3', private.course_get_item(content, '6.3') || jsonb_build_object('drillBank', coalesce(private.course_get_item(content, '6.3')->'drillBank','[]'::jsonb) || $j$[{"id":"m7-6-3-d10","type":"single","number":10,"prompt":"Which appointment time is set correctly?","options":[{"id":"A","text":"\"Thursday at 6 PM Eastern\"","correct":true},{"id":"B","text":"\"Thursday evening\"","correct":false},{"id":"C","text":"\"Sometime after work Thursday\"","correct":false},{"id":"D","text":"\"Thursday, whenever Joan gets home\"","correct":false}],"explanation":"Lesson 6.3. Date, time and time zone out loud."}]$j$::jsonb)) where id = 'm7';
update public.course_modules set content = private.course_put_item(content, '6.5', private.course_get_item(content, '6.5') || jsonb_build_object('drillBank', coalesce(private.course_get_item(content, '6.5')->'drillBank','[]'::jsonb) || $j$[{"id":"m7-6-5-d10","type":"single","number":10,"prompt":"A callback is due at 2:00 PM ET and a new inbound lead lands at 1:58. What do you do?","options":[{"id":"A","text":"Book the new lead for 2:30, then call at 2:00","correct":true},{"id":"B","text":"Skip the callback, since new leads always come first","correct":false},{"id":"C","text":"Let the new lead wait until 3:00","correct":false},{"id":"D","text":"Text the callback to say you're running late","correct":false}],"explanation":"Lesson 6.5."},{"id":"m7-6-5-d11","type":"single","number":11,"prompt":"A lead is unreachable after the full cadence. What status, and what goes with it?","options":[{"id":"A","text":"Nurture, no note needed","correct":false},{"id":"B","text":"New, so it gets called again","correct":false},{"id":"C","text":"Do-not-call","correct":false},{"id":"D","text":"Dead, with the reason noted","correct":true}],"explanation":"Lesson 6.5. Dead always has a reason."}]$j$::jsonb)) where id = 'm7';
update public.course_modules set content = private.course_put_item(content, '13.4', private.course_get_item(content, '13.4') || jsonb_build_object('drillBank', coalesce(private.course_get_item(content, '13.4')->'drillBank','[]'::jsonb) || $j$[{"id":"m18-13-4-d10","type":"single","number":10,"prompt":"Which deal-blast line is right?","options":[{"id":"A","text":"\"We're selling this house.\"","correct":false},{"id":"B","text":"\"For sale: 3 bed, 2 bath, $91,500, cash only, close in 14 days, investors welcome\"","correct":false},{"id":"C","text":"\"We have a property under contract and are assigning our contract interest.\"","correct":true},{"id":"D","text":"\"Owner says come anytime.\"","correct":false}],"explanation":"Lesson 13.4."},{"id":"m18-13-4-d11","type":"single","number":11,"prompt":"Can you list a contracted house on the MLS yourself?","options":[{"id":"A","text":"Yes, if the seller agrees","correct":false},{"id":"B","text":"No, the MLS is for licensed brokers","correct":true},{"id":"C","text":"Yes, once the inspection period has ended","correct":false},{"id":"D","text":"Only in Ohio","correct":false}],"explanation":"Lesson 13.4."}]$j$::jsonb)) where id = 'm18';
update public.course_modules set content = private.course_put_item(content, '13.6', private.course_get_item(content, '13.6') || jsonb_build_object('drillBank', coalesce(private.course_get_item(content, '13.6')->'drillBank','[]'::jsonb) || $j$[{"id":"m18-13-6-d10","type":"single","number":10,"prompt":"A buyer asks if a neighborhood is \"a family area.\" What do you do?","options":[{"id":"A","text":"Tell them honestly about the people who live there","correct":false},{"id":"B","text":"Say yes so they stay interested","correct":false},{"id":"C","text":"Describe the house, not who lives there","correct":true},{"id":"D","text":"Steer them to a different area","correct":false}],"explanation":"Lesson 13.6, fair housing."},{"id":"m18-13-6-d11","type":"single","number":11,"prompt":"A grieving, confused seller wants to sign tonight. What do you do?","options":[{"id":"A","text":"Get it signed tonight before they have a chance to change their mind","correct":false},{"id":"B","text":"Slow down and suggest family or a lawyer looks at it first","correct":true},{"id":"C","text":"Sign now and explain later","correct":false},{"id":"D","text":"Lower the offer since they're motivated","correct":false}],"explanation":"Lesson 13.6."}]$j$::jsonb)) where id = 'm18';
update public.course_modules set content = private.course_put_item(content, '13.5', private.course_get_item(content, '13.5') || jsonb_build_object('drillBank', coalesce(private.course_get_item(content, '13.5')->'drillBank','[]'::jsonb) || $j$[{"id":"m18-13-5-d10","type":"single","number":10,"prompt":"Which of these is an all-party consent state for recording?","options":[{"id":"A","text":"Ohio","correct":false},{"id":"B","text":"North Carolina","correct":false},{"id":"C","text":"Maryland","correct":true},{"id":"D","text":"Texas","correct":false}],"explanation":"Lesson 13.5."}]$j$::jsonb)) where id = 'm18';
update private.course_settings set value = '["m20/20.6"]'::jsonb, updated_at = now() where key = 'compliance_items';